mapper.select:
SELECT id AS notification_id, noti_type, title, content, source_type, source_id, work_case_id, is_read, read_at, created_at FROM notifications WHERE recipient_user_id = #{recipientUserId}
AND is_read = 0
ORDER BY created_at DESC, id DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE notifications
SET is_read = 1,
    read_at = NOW(6)
WHERE id = #{notificationId}
  AND recipient_user_id = #{recipientUserId}
  AND is_read = 0

mapper.select:
SELECT COUNT(*)
FROM notifications
WHERE id = #{notificationId}
  AND recipient_user_id = #{recipientUserId}
